```typescript
import {
  Table,
  Column,
  Model,
  DataType,
  CreatedAt,
  UpdatedAt,
  DeletedAt,
  BeforeCreate,
  BeforeUpdate,
  IsEmail,
  Length,
  Unique,
  AllowNull,
  Default,
  PrimaryKey,
  AutoIncrement,
  Is,
} from 'sequelize-typescript';
import bcrypt from 'bcrypt';

export enum UserRole {
  ADMIN = 'admin',
  USER = 'user',
  MODERATOR = 'moderator',
}

@Table({
  tableName: 'users',
  paranoid: true,        // enables soft delete (uses deletedAt)
  underscored: true,     // uses snake_case for column names
  timestamps: true,      // enables createdAt and updatedAt
})
export class User extends Model {
  @PrimaryKey
  @AutoIncrement
  @Column(DataType.INTEGER)
  id: number;

  @AllowNull(false)
  @Length({ min: 2, max: 50 })
  @Column(DataType.STRING)
  firstName: string;

  @AllowNull(false)
  @Length({ min: 2, max: 50 })
  @Column(DataType.STRING)
  lastName: string;

  @AllowNull(false)
  @Unique
  @IsEmail
  @Column(DataType.STRING)
  email: string;

  @AllowNull(false)
  @Length({ min: 8 })
  @Column(DataType.STRING)
  password: string;

  @AllowNull(true)
  @Is(/^\+?[1-9]\d{1,14}$/)   // E.164 phone format
  @Column(DataType.STRING)
  phone: string | null;

  @AllowNull(false)
  @Default(UserRole.USER)
  @Column(DataType.ENUM(...Object.values(UserRole)))
  role: UserRole;

  @AllowNull(false)
  @Default(true)
  @Column(DataType.BOOLEAN)
  isActive: boolean;

  @AllowNull(true)
  @Column(DataType.DATE)
  lastLoginAt: Date | null;

  @CreatedAt
  @Column(DataType.DATE)
  createdAt: Date;

  @UpdatedAt
  @Column(DataType.DATE)
  updatedAt: Date;

  @DeletedAt
  @Column(DataType.DATE)
  deletedAt: Date | null;

  // ─── Virtual Field ───────────────────────────────────────────────────
  @Column(DataType.VIRTUAL)
  get fullName(): string {
    return `${this.firstName} ${this.lastName}`;
  }

  // ─── Hooks ───────────────────────────────────────────────────────────
  @BeforeCreate
  @BeforeUpdate
  static async hashPassword(instance: User): Promise<void> {
    if (instance.changed('password')) {
      const salt = await bcrypt.genSalt(10);
      instance.password = await bcrypt.hash(instance.password, salt);
    }
  }

  // ─── Instance Methods ─────────────────────────────────────────────────
  async validatePassword(plainPassword: string): Promise<boolean> {
    return bcrypt.compare(plainPassword, this.password);
  }

  toSafeJSON(): Omit<User, 'password'> {
    const { password, ...safeUser } = this.toJSON() as User;
    return safeUser;
  }
}
