---

### 2. Full Example: Train + Save + Inference

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <fann.h>

// ═══════════════════════════════════════════════════════════
//  STEP 1: Create & Train Network
// ═══════════════════════════════════════════════════════════
void trainNetwork(const std::string& model_path, 
                  const std::string& data_path) {

    const unsigned int num_layers    = 3;
    const unsigned int num_input     = 2;
    const unsigned int num_hidden    = 4;
    const unsigned int num_output    = 1;
    const unsigned int max_epochs    = 500000;
    const unsigned int report_epochs = 1000;
    const float desired_error        = 0.001f;

    // Create network topology: 2 → 4 → 1
    struct fann* ann = fann_create_standard(
        num_layers, 
        num_input, 
        num_hidden, 
        num_output
    );

    // Set activation functions
    fann_set_activation_function_hidden(ann, FANN_SIGMOID_SYMMETRIC);
    fann_set_activation_function_output(ann, FANN_SIGMOID_SYMMETRIC);

    // Set training algorithm
    fann_set_training_algorithm(ann, FANN_TRAIN_RPROP);

    // Train on XOR dataset
    fann_train_on_file(
        ann, 
        data_path.c_str(), 
        max_epochs, 
        report_epochs, 
        desired_error
    );

    // Save trained model
    fann_save(ann, model_path.c_str());
    std::cout << "Model saved to: " << model_path << std::endl;

    fann_destroy(ann);
}

// ═══════════════════════════════════════════════════════════
//  STEP 2: Inference Class (Reusable)
// ═══════════════════════════════════════════════════════════
class FANNInference {
private:
    struct fann* ann_;
    unsigned int num_inputs_;
    unsigned int num_outputs_;

public:
    // Constructor: load model
    explicit FANNInference(const std::string& model_path) 
        : ann_(nullptr) {

        ann_ = fann_create_from_file(model_path.c_str());

        if (!ann_) {
            throw std::runtime_error(
                "Failed to load model: " + model_path
            );
        }

        num_inputs_  = fann_get_num_input(ann_);
        num_outputs_ = fann_get_num_output(ann_);

        std::cout << "✓ Model loaded: " << model_path        << std::endl;
        std::cout << "  Inputs:       " << num_inputs_        << std::endl;
        std::cout << "  Outputs:      " << num_outputs_       << std::endl;
        std::cout << "  Layers:       " 
                  << fann_get_num_layers(ann_)                << std::endl;
        std::cout << "  Connections:  " 
                  << fann_get_total_connections(ann_)         << std::endl;
    }

    // Destructor: cleanup
    ~FANNInference() {
        if (ann_) {
            fann_destroy(ann_);
            ann_ = nullptr;
        }
    }

    // Prevent copy
    FANNInference(const FANNInference&)            = delete;
    FANNInference& operator=(const FANNInference&) = delete;

    // ─────────────────────────────────────────
    // Single inference
    // ─────────────────────────────────────────
    std::vector<float> predict(const std::vector<float>& inputs) {

        if (inputs.size() != num_inputs_) {
            throw std::invalid_argument(
                "Input size mismatch! Expected: " + 
                std::to_string(num_inputs_) + 
                " Got: " + 
                std::to_string(inputs.size())
            );
        }

        // Convert to fann_type array
        std::vector<fann_type> fann_input(num_inputs_);
        for (unsigned int i = 0; i < num_inputs_; i++) {
            fann_input[i] = static_cast<fann_type>(inputs[i]);
        }

        // Run inference
        fann_type* raw_output = fann_run(ann_, fann_input.data());

        // Convert output
        std::vector<float> result(num_outputs_);
        for (unsigned int i = 0; i < num_outputs_; i++) {
            result[i] = static_cast<float>(raw_output[i]);
        }

        return result;
    }

    // ─────────────────────────────────────────
    // Batch inference
    // ─────────────────────────────────────────
    std::vector<std::vector<float>> predictBatch(
        const std::vector<std::vector<float>>& batch) {

        std::vector<std::vector<float>> results;
        results.reserve(batch.size());

        for (const auto& sample : batch) {
            results.push_back(predict(sample));
        }

        return results;
    }

    // ─────────────────────────────────────────
    // Getters
    // ─────────────────────────────────────────
    unsigned int getNumInputs()  const { return num_inputs_;  }
    unsigned int getNumOutputs() const { return num_outputs_; }

    // Print network info
    void printInfo() const {
        std::cout << "\n──── Network Info ────" << std::endl;

        unsigned int num_layers = fann_get_num_layers(ann_);
        std::vector<unsigned int> layers(num_layers);
        fann_get_layer_array(ann_, layers.data());

        std::cout << "Topology: ";
        for (unsigned int i = 0; i < num_layers; i++) {
            std::cout << layers[i];
            if (i < num_layers - 1) std::cout << " → ";
        }
        std::cout << std::endl;

        std::cout << "MSE: " << fann_get_MSE(ann_) << std::endl;
        std::cout << "─────────────────────" << std::endl;
    }
};

// ═══════════════════════════════════════════════════════════
//  STEP 3: Main - XOR Example
// ═══════════════════════════════════════════════════════════
int main() {
    const std::string model_path = "xor_model.net";
    const std::string data_path  = "xor.data";

    // ─── Create XOR training data file ───────
    // xor.data format:
    // num_samples num_inputs num_outputs
    // input1 input2
    // output
    {
        std::ofstream file(data_path);
        file << "4 2 1\n";
        file << "-1 -1\n-1\n";
        file << "-1  1\n 1\n";
        file << " 1 -1\n 1\n";
        file << " 1  1\n-1\n";
    }

    // ─── Train ───────────────────────────────
    std::cout << "═══ Training Phase ═══" << std::endl;
    trainNetwork(model_path, data_path);

    // ─── Inference ───────────────────────────
    std::cout << "\n═══ Inference Phase ═══" << std::endl;

    try {
        FANNInference model(model_path);
        model.printInfo();

        // Test XOR cases
        std::vector<std::vector<float>> test_cases = {
            {-1.0f, -1.0f},   // Expected: -1 (False XOR False)
            {-1.0f,  1.0f},   // Expected:  1 (False XOR True)
            { 1.0f, -1.0f},   // Expected:  1 (True  XOR False)
            { 1.0f,  1.0f}    // Expected: -1 (True  XOR True)
        };

        std::vector<float> expected = {-1.0f, 1.0f, 1.0f, -1.0f};

        std::cout << "\n┌──────────────┬────────────┬──────────┐" << std::endl;
        std::cout << "│   Inputs     │  Expected  │  Output  │" << std::endl;
        std::cout << "├──────────────┼────────────┼──────────┤" << std::endl;

        for (size_t i = 0; i < test_cases.size(); i++) {
            auto output = model.predict(test_cases[i]);

            printf("│ [%4.1f, %4.1f] │   %5.2f    │  %5.4f  │\n",
                test_cases[i][0],
                test_cases[i][1],
                expected[i],
                output[0]
            );
        }

        std::cout << "└──────────────┴────────────┴──────────┘" << std::endl;

        // ─── Batch Inference ─────────────────
        std::cout << "\n═══ Batch Inference ═══" << std::endl;
        auto batch_results = model.predictBatch(test_cases);

        for (size_t i = 0; i < batch_results.size(); i++) {
            std::cout << "Batch[" << i << "]: " << batch_results[i][0] << std::endl;
        }

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
