1. **Offsets**: The offsets used in this program (`OFFSET_LOCAL_PLAYER`, `OFFSET_HEALTH`, `OFFSET_TEAM`) are placeholders and need to be replaced with the actual offsets for the current version of CS:GO. You can find these offsets on websites like `hazedumper` or `github.com/frk1/hazedumper`.

2. **Administrator privileges**: This program requires administrator privileges to read another process's memory.

3. **Anti-cheat**: CS:GO has an anti-cheat system (VAC) that may detect and ban you for using this type of program. Use this at your own risk.

4. **Legal and ethical considerations**: Using memory reading programs in online games may violate the game's terms of service and could result in a ban. This code is provided for educational purposes only.

5. **32-bit vs 64-bit**: CS:GO is a 32-bit application, so you may need to adjust the pointer size accordingly. The `readLong` method reads 8 bytes, but for a 32-bit application, you should use `readInt` and cast to `long`.

Here's a simple Rust function to convert a decimal string like `"1"` to its hexadecimal equivalent:

```rust
fn decimal_to_hex(decimal_str: &str) -> Result<String, std::num::ParseIntError> {
    let decimal: u64 = decimal_str.trim().parse()?;
    Ok(format!("{:X}", decimal))
}

fn main() {
    let examples = vec!["1", "10", "255", "256", "1000"];

    for num in examples {
        match decimal_to_hex(num) {
            Ok(hex) => println!("{} => 0x{}", num, hex),
            Err(e) => println!("Error converting '{}': {}", num, e),
        }
    }
}
```

### Output:
```
1 => 0x1
10 => 0xA
255 => 0xFF
256 => 0x100
1000 => 0x3E8
```

### Key Points:
- **`parse::<u64>()`** — Converts the string to an unsigned 64-bit integer.
- **`{:X}`** — Formats the number as **uppercase** hex. Use `{:x}` for lowercase.
- **`Result`** — Handles invalid input gracefully (e.g., non-numeric strings).

---

### With lowercase hex and `0x` prefix:
```rust
fn decimal_to_hex(decimal_str: &str) -> Result<String, std::num::ParseIntError> {
    let decimal: u64 = decimal_str.trim().parse()?;
    Ok(format!("0x{:x}", decimal))
}
```

### Output:
```
1 => 0x1
255 => 0xff
1000 => 0x3e8
```

# ESP-NOW Master Code Example

Here's a complete ESP-NOW **Master (Sender)** code example for ESP32:

---

## Master (Sender) Code

```cpp
#include <Arduino.h>
#include <esp_now.h>
#include <WiFi.h>

// =============================================
// Configuration
// =============================================

// Replace with your Slave MAC Address
uint8_t slaveMAC[] = {0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF};

// Data structure to send
typedef struct MessageData {
  int id;
  float temperature;
  float humidity;
  char message[32];
} MessageData;

MessageData dataToSend;
esp_now_peer_info_t peerInfo;

// =============================================
// Callback Functions
// =============================================

// Called when data is sent
void OnDataSent(const uint8_t *mac_addr, esp_now_send_status_t status) {
  Serial.print("Last Packet Send Status: ");
  if (status == ESP_NOW_SEND_SUCCESS) {
    Serial.println("✅ Delivery Success");
  } else {
    Serial.println("❌ Delivery Fail");
  }
}

// =============================================
// Setup
// =============================================

void setup() {
  Serial.begin(115200);
  Serial.println("\n=== ESP-NOW Master ===");

  // Set device as a Wi-Fi Station
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();

  // Print MAC Address
  Serial.print("Master MAC Address: ");
  Serial.println(WiFi.macAddress());

  // Initialize ESP-NOW
  if (esp_now_init() != ESP_OK) {
    Serial.println("❌ Error initializing ESP-NOW");
    return;
  }

  // Register send callback
  esp_now_register_send_cb(OnDataSent);

  // Register peer (slave)
  memcpy(peerInfo.peer_addr, slaveMAC, 6);
  peerInfo.channel = 0;
  peerInfo.encrypt = false;

  if (esp_now_add_peer(&peerInfo) != ESP_OK) {
    Serial.println("❌ Failed to add peer");
    return;
  }

  Serial.println("✅ ESP-NOW Initialized");
  Serial.println("✅ Peer Added Successfully");
}

// =============================================
// Loop
// =============================================

void loop() {
  // Populate data
  dataToSend.id++;
  dataToSend.temperature = random(200, 350) / 10.0;  // 20.0 - 35.0
  dataToSend.humidity    = random(400, 900) / 10.0;  // 40.0 - 90.0
  snprintf(dataToSend.message, sizeof(dataToSend.message), "Hello from Master #%d", dataToSend.id);

  // Send data
  esp_err_t result = esp_now_send(slaveMAC, (uint8_t *)&dataToSend, sizeof(dataToSend));

  if (result == ESP_OK) {
    Serial.println("📤 Data Sent:");
    Serial.printf("   ID          : %d\n",   dataToSend.id);
    Serial.printf("   Temperature : %.1f°C\n", dataToSend.temperature);
    Serial.printf("   Humidity    : %.1f%%\n",  dataToSend.humidity);
    Serial.printf("   Message     : %s\n",    dataToSend.message);
  } else {
    Serial.println("❌ Error sending data");
  }

  delay(3000);  // Send every 3 seconds
}
```

---

## Slave (Receiver) Code

```cpp
#include <Arduino.h>
#include <esp_now.h>
#include <WiFi.h>

// =============================================
// Data structure (must match Master)
// =============================================

typedef struct MessageData {
  int id;
  float temperature;
  float humidity;
  char message[32];
} MessageData;

MessageData receivedData;

// =============================================
// Callback Functions
// =============================================

// Called when data is received
void OnDataReceived(const esp_now_recv_info_t *recvInfo, const uint8_t *incomingData, int len) {
  memcpy(&receivedData, incomingData, sizeof(receivedData));

  Serial.println("\n📥 Data Received:");
  Serial.printf("   From MAC    : %02X:%02X:%02X:%02X:%02X:%02X\n",
    recvInfo->src_addr[0], recvInfo->src_addr[1], recvInfo->src_addr[2],
    recvInfo->src_addr[3], recvInfo->src_addr[4], recvInfo->src_addr[5]);
  Serial.printf("   ID          : %d\n",     receivedData.id);
  Serial.printf("   Temperature : %.1f°C\n", receivedData.temperature);
  Serial.printf("   Humidity    : %.1f%%\n",  receivedData.humidity);
  Serial.printf("   Message     : %s\n",     receivedData.message);
  Serial.printf("   Data Size   : %d bytes\n", len);
}

// =============================================
// Setup
// =============================================

void setup() {
  Serial.begin(115200);
  Serial.println("\n=== ESP-NOW Slave ===");

  // Set device as a Wi-Fi Station
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();

  // Print MAC Address
  Serial.print("Slave MAC Address: ");
  Serial.println(WiFi.macAddress());

  // Initialize ESP-NOW
  if (esp_now_init() != ESP_OK) {
    Serial.println("❌ Error initializing ESP-NOW");
    return;
  }

  // Register receive callback
  esp_now_register_recv_cb(OnDataReceived);

  Serial.println("✅ ESP-NOW Initialized");
  Serial.println("⏳ Waiting for data...");
}

// =============================================
// Loop
// =============================================

void loop() {
  // Nothing needed here
  // Data received via callback
  delay(1000);
}
```

